// RPC models. Embedded in NITF (RPC00B) or GeoTIFF tags they arrive as layer.tags.rpc. From a
// DigitalGlobe .RPB sidecar the loader stores layer.sidecar.rpc, with the .TIL tile offset in
// layer.sidecar.offset. rpcOf(layer) returns the record from either place, or null.
export function rpcOf(layer) {
  const record = layer.tags?.rpc ?? layer.sidecar?.rpc;
  if (!record) return null;
  const [dl, ds] = layer.sidecar?.offset ?? [0, 0];
  return { ...record, lineOff: record.lineOff - dl, sampOff: record.sampOff - ds };
}

// Image (line, sample) of a ground point, to first order.
export function project(rpc, [lon, lat]) {
  const { lineOff, sampOff, lineScale, sampScale, latOff, lonOff, latScale, lonScale } = rpc;
  return [lineOff - ((lat - latOff) / latScale) * lineScale, sampOff + ((lon - lonOff) / lonScale) * sampScale];
}

head.src/align.js:
import { project } from './rpc.js';

// Stereo > Align: line and sample bias corrections for two images, from tie points.
export function alignPair(left, right, ties) {
  const models = [left, right].map((layer) => layer.tags.rpc);
  const bias = models.map(() => ({ line: 0, sample: 0 }));
  for (const tie of ties) {
    models.forEach((model, k) => {
      const [line, sample] = project(model, tie.ground);
      bias[k].line += (tie.image[k][1] - line) / ties.length;
      bias[k].sample += (tie.image[k][0] - sample) / ties.length;
    });
  }
  return bias;
}
